SELECT COUNT(1) AS count, sum(apply_amount) total FROM aid_work
WHERE deleted = 0

    AND status = #{status}


    AND create_time >= #{startTime} and create_time  <=  #{endTime}

SELECT status AS status, COUNT(1) AS count FROM aid_work WHERE deleted = 0
AND create_time >= #{startTime} and create_time <= #{endTime}
GROUP BY status

SELECT aid_type AS type, COUNT(1) AS count FROM aid_work WHERE deleted = 0
AND create_time >= #{startTime} and create_time <= #{endTime}
GROUP BY aid_type

SELECT `status` AS status, COUNT(1) AS count FROM aid_work
WHERE deleted = 0

    AND aid_type = #{type}


    AND create_time >= #{startTime} and create_time  <=  #{endTime}

GROUP BY `status`
